[project]
name = "recognition"
version = "0.1.0"
description = "Architecture-as-code harness: turns an IFC model into schedules, compliance reports and 2D drawings so Devin can govern detailing like software."
requires-python = ">=3.12"
dependencies = [
    "ifcopenshell>=0.8.5",
    "shapely>=2.1",
    "svgwrite>=1.4",
    "cairosvg>=2.7",
    "ezdxf>=1.3",
    "pyyaml>=6.0",
    "fastapi>=0.141.1",
    "uvicorn[standard]>=0.52.4",
    "python-multipart>=0.0.32",
    "jinja2>=3.1.6",
    "httpx>=0.28.1",
]

[project.scripts]
recognition = "recognition.cli:main"
recognition-ui = "ui.app:main"

[dependency-groups]
dev = ["pytest>=8.0"]

[build-system]
requires = ["hatchling"]
build-backend = "hatchling.build"

[tool.hatch.build.targets.wheel]
packages = ["recognition", "ui"]

[tool.pytest.ini_options]
testpaths = ["tests"]
